const b = $json.body || {};
const clean = (v, max = 255) => String(v || '').trim().slice(0, max);
const missing = (v) => v === undefined || v === null || String(v).trim() === '';
const fail = (message) => [{ json: { ok: false, error: { code: 'VALIDATION_ERROR', message } } }];
if (missing(b.slotId)) return fail('Le champ slotId est obligatoire.');
if (missing(b.nom)) return fail('Le champ nom est obligatoire.');
if (missing(b.prenom)) return fail('Le champ prénom est obligatoire.');
const slotId = String(b.slotId).trim();
if (!/^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(slotId)) return fail('Le champ slotId est invalide.');
return [{
  json: {
    ok: true,
    slotId,
    nom: clean(b.nom, 100),
    prenom: clean(b.prenom, 100),
    email: clean(b.email, 255),
    telephone: clean(b.telephone, 50),
    numeroDocument: clean(b.numeroDocument, 100),
    langue: clean(b.langue || 'fr', 10)
  }
}];

const appointment = $json || {};

if (!appointment.id) {
  return [{
    json: {
      success: false,
      created: false,
      message: 'Créneau introuvable ou complet'
    }
  }];
}

return [{
  json: {
    success: true,
    created: true,
    appointment
  }
}];

